    and     #$03                    ; $A904
    bne     @done                   ; $A906
    inc     oamBuffer+108           ; $A908
    inc     oamBuffer+108           ; $A90B
    inc     oamBuffer+111           ; $A90E
    inc     oamBuffer+111           ; $A911
    inc     oamBuffer+111           ; $A914

@done:
