    ldx     #$02                    ; $B3DF

@loop:
    txa                             ; $B3E1
    pha                             ; $B3E2
    jsr     Save_RestoreFromBackup  ; $B3E3
    pla                             ; $B3E6
    tax                             ; $B3E7
